import {searchProducts} from './search-core.js';
import {fitRect,constrainLogo,hitLogo,logoDimensions} from './logo-layout.js';
const root=document.querySelector('[data-logo-studio]');
if(root){
 const $=id=>document.getElementById(id),canvas=$('logo-canvas'),ctx=canvas.getContext('2d'),status=$('logo-status');
 let all=[],product=null,photo=null,logo=null,state={x:500,y:600,size:25,angle:0,opacity:100},drag=null,photoVersion=0,logoVersion=0;
 const message=text=>status.textContent=text;
 function update(){if(logo)state=constrainLogo(state,logo.naturalWidth/logo.naturalHeight);$('logo-x').value=state.x/10;$('logo-y').value=state.y/10;$('logo-size').value=state.size;$('logo-angle').value=state.angle;$('logo-opacity').value=state.opacity;$('logo-size-value').textContent=state.size+'%';$('logo-angle-value').textContent=state.angle+'°';$('logo-opacity-value').textContent=state.opacity+'%';$('logo-adjust').disabled=!logo;$('logo-download').disabled=!(photo&&logo);draw();}
 function draw(selection=true){ctx.clearRect(0,0,1000,1000);ctx.fillStyle='#fff';ctx.fillRect(0,0,1000,1000);if(photo){const r=fitRect(photo.naturalWidth,photo.naturalHeight);ctx.drawImage(photo,r.x,r.y,r.width,r.height);}else{ctx.fillStyle='#64747c';ctx.font='22px "Noto Sans Thai", sans-serif';ctx.textAlign='center';ctx.fillText('เลือกสินค้าเพื่อเริ่มวางโลโก้',500,450);}if(logo&&photo){const {width:w,height:h}=logoDimensions(state,logo.naturalWidth/logo.naturalHeight);ctx.save();ctx.translate(state.x,state.y);ctx.rotate(state.angle*Math.PI/180);ctx.globalAlpha=state.opacity/100;ctx.drawImage(logo,-w/2,-h/2,w,h);ctx.globalAlpha=1;if(selection){ctx.strokeStyle='#008b8d';ctx.lineWidth=2;ctx.setLineDash([8,6]);ctx.strokeRect(-w/2-5,-h/2-5,w+10,h+10);}ctx.restore();}ctx.textAlign='left';ctx.font='18px "Noto Sans Thai", sans-serif';ctx.fillStyle='#006466';ctx.fillText('Smart Gift',40,952);ctx.font='16px "Noto Sans Thai", sans-serif';ctx.fillStyle='#64747c';ctx.fillText((product?.sku||'')+' · ภาพจำลองตำแหน่งโลโก้ · ยืนยันแบบก่อนผลิต',40,980);}
 function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('image'));img.src=src;});}
 async function loadPhoto(){const version=++photoVersion;photo=null;update();message('กำลังโหลดภาพสินค้า…');const index=Number($('logo-view').value)||0;const src=(product.images||[product.image])[index]||product.image;try{const url=src.startsWith('/')?src:'/product-image?sku='+encodeURIComponent(product.sku)+'&view='+index;const img=await loadImage(url);if(version!==photoVersion)return;photo=img;message(logo?'ลากโลโก้หรือปรับตำแหน่งได้เลย':'เลือกไฟล์โลโก้เพื่อเริ่มจัดวาง');update();}catch{if(version===photoVersion){message('ภาพสินค้านี้ยังโหลดไม่ได้ กรุณาเลือกภาพอื่นหรือสินค้าอื่นแล้วลองใหม่');update();}}}
 function choose(sku){const p=all.find(p=>p.sku===sku);if(!p)return;product=p;$('logo-product-link').href=p.url;$('logo-quote').href='/smartgift/contact?product='+encodeURIComponent(p.sku);$('logo-view').replaceChildren(...(p.images||[p.image]).filter(Boolean).map((src,i)=>new Option('ภาพที่ '+(i+1),i)));$('logo-view').disabled=false;const u=new URL(location.href);u.searchParams.set('sku',p.sku);history.replaceState(null,'',u);loadPhoto();}
 function populate(query='',preferred){const found=searchProducts(all,query);let shown=found.slice(0,30);const selected=all.find(p=>p.sku===preferred);if(selected&&!shown.some(p=>p.sku===selected.sku))shown=[selected,...shown.slice(0,29)];$('logo-product').replaceChildren(...shown.map(p=>new Option(p.sku+' · '+p.title,p.sku)));$('logo-product').disabled=!shown.length;$('logo-search-count').textContent=found.length>30?`พบ ${found.length.toLocaleString('th-TH')} รายการ แสดง 30 รายการแรก ลองระบุชื่อหรือรหัสเพิ่ม`:found.length?`พบ ${found.length.toLocaleString('th-TH')} รายการ`:'ไม่พบสินค้า ลองคำค้นอื่น';if(selected)$('logo-product').value=selected.sku;return shown;}
 $('logo-product-search').addEventListener('submit',e=>{e.preventDefault();const found=populate($('logo-query').value);if(found.length)choose(found[0].sku);});$('logo-product').addEventListener('change',()=>choose($('logo-product').value));$('logo-view').addEventListener('change',loadPhoto);
 $('logo-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const version=++logoVersion;if(!['image/png','image/jpeg','image/webp'].includes(file.type)){message('กรุณาใช้ไฟล์ PNG, JPG หรือ WebP');e.target.value='';return;}if(file.size>10*1024*1024){message('ไฟล์ใหญ่เกิน 10 MB กรุณาเลือกไฟล์ขนาดเล็กลง');e.target.value='';return;}const objectUrl=URL.createObjectURL(file);try{const img=await loadImage(objectUrl);if(version!==logoVersion)return;if(img.naturalWidth>12000||img.naturalHeight>12000)throw Error('dimensions');logo=img;state={x:500,y:600,size:25,angle:0,opacity:100};message('อัปโหลดโลโก้แล้ว ลากบนภาพเพื่อวางตำแหน่งที่ต้องการ');update();}catch{message('เปิดไฟล์ภาพนี้ไม่ได้ หรือภาพใหญ่เกิน 12,000 พิกเซล กรุณาเลือกไฟล์อื่น');}finally{URL.revokeObjectURL(objectUrl);}});
 for(const [id,key,factor] of [['logo-size','size',1],['logo-angle','angle',1],['logo-opacity','opacity',1],['logo-x','x',10],['logo-y','y',10]])$(id).addEventListener('input',()=>{state[key]=Number($(id).value)*factor;update();});
 $('logo-reset').addEventListener('click',()=>{state={x:500,y:600,size:25,angle:0,opacity:100};update();});$('logo-remove').addEventListener('click',()=>{++logoVersion;logo=null;$('logo-file').value='';update();message('นำโลโก้ออกแล้ว');});
 const point=e=>{const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left)*1000/r.width,y:(e.clientY-r.top)*1000/r.height}};
 canvas.addEventListener('pointerdown',e=>{if(!photo||!logo)return;const p=point(e);if(!hitLogo(p,state,logo.naturalWidth/logo.naturalHeight))return;drag={id:e.pointerId,x:p.x-state.x,y:p.y-state.y};canvas.setPointerCapture(e.pointerId);canvas.focus();e.preventDefault();});canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const p=point(e);state.x=p.x-drag.x;state.y=p.y-drag.y;update();});for(const type of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(type,()=>drag=null);
 canvas.addEventListener('keydown',e=>{if(!logo||!photo)return;const delta=e.shiftKey?10:2;if(e.key==='ArrowLeft')state.x-=delta;else if(e.key==='ArrowRight')state.x+=delta;else if(e.key==='ArrowUp')state.y-=delta;else if(e.key==='ArrowDown')state.y+=delta;else return;e.preventDefault();update();});
 $('logo-download').addEventListener('click',async()=>{if(!photo||!logo)return;try{await document.fonts.ready;draw(false);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error();const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='SmartGift-'+product.sku+'-logo-preview.png';link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);message('ดาวน์โหลดภาพแล้ว แนบภาพนี้ส่งผ่าน LINE เพื่อให้ทีมตรวจแบบและขอราคาได้เลย');}catch{message('บันทึกภาพไม่ได้ กรุณาลองเลือกภาพอื่นอีกครั้ง');}finally{draw();}});
 draw();try{const r=await fetch('/data/search-index.json');if(!r.ok)throw Error();all=await r.json();const sku=new URLSearchParams(location.search).get('sku')||'SG-900001';populate('',sku);if(all.some(p=>p.sku===sku))choose(sku);else message('ไม่พบสินค้านี้ในแค็ตตาล็อกปัจจุบัน กรุณาค้นหาและเลือกสินค้าอื่น');}catch{message('โหลดรายการสินค้าไม่ได้ กรุณารีเฟรชหน้านี้แล้วลองอีกครั้ง');}
}
